export async function createOrder(input: NewOrder, idempotencyKey: string) {
  return db.transaction(async (tx) => {
    // Claim the key first. The unique index is what makes this safe when two
    // requests arrive in the same millisecond - one of them loses here.
    try {
      await tx.insert(idempotencyKeys).values({ key: idempotencyKey });
    } catch (err) {
      if (!isUniqueViolation(err)) throw err;
      const existing = await tx.query.orders.findFirst({
        where: eq(orders.idempotencyKey, idempotencyKey),
      });
      if (existing) return existing; // same request, same answer
      throw new ConflictError('Request already in progress');
    }

    // SELECT ... FOR UPDATE. Read-decide-write without this loses one of two
    // concurrent decrements and oversells the last item.
    const stock = await tx.query.stock.findFirst({
      where: eq(stock.sku, input.sku),
      for: 'update',
    });
    if (!stock || stock.available < input.quantity) {
      throw new UnprocessableError('INSUFFICIENT_STOCK', { sku: input.sku });
    }

    await tx.update(stock)
      .set({ available: stock.available - input.quantity })
      .where(eq(stock.sku, input.sku));

    const [order] = await tx.insert(orders)
      .values({ ...input, idempotencyKey })
      .returning();

    // Outbox, not a direct send. A rolled-back transaction must not have
    // emailed anyone, and a crash here must not lose the message.
    await tx.insert(outbox).values({
      topic: 'order.created',
      payload: { orderId: order.id },
    });

    return order;
  });
}
